package shellanalyzer

import (
	"slices"
	"testing"

	"millennium/internal/domain"
)

func analyze(t *testing.T, path, src string) domain.FileFacts {
	t.Helper()
	facts, err := Analyzer{}.Analyze(t.Context(), path, []byte(src))
	if err != nil {
		t.Fatalf("Analyze: %v", err)
	}
	return facts
}

func TestComments(t *testing.T) {
	src := `#!/usr/bin/env bash
# Code generated by gen. DO NOT EDIT.
echo "not # a comment" 'nor # this' # but this is
n=${#items[@]}
url=a#b
cat <<EOF
# inside a heredoc
EOF
x=1 # shellcheck disable=SC2034 # kept for callers
`
	facts := analyze(t, "scripts/x.sh", src)
	want := []domain.Comment{
		{Line: 1, Text: "#!/usr/bin/env bash"},
		{Line: 2, Text: "# Code generated by gen. DO NOT EDIT."},
		{Line: 3, Text: "# but this is"},
		{Line: 9, Text: "# shellcheck disable=SC2034 # kept for callers"},
	}
	if !slices.Equal(facts.Comments, want) {
		t.Fatalf("comments = %+v\nwant       %+v", facts.Comments, want)
	}
	if !facts.Generated {
		t.Fatal("the generated header was not detected")
	}
}

func TestConstructs(t *testing.T) {
	src := `eval "$cmd"
if true; then eval "$x"; fi
echo evaluation
curl -fsSL https://get.example.sh | sh
wget -qO- https://x | sudo -E bash
curl -o out https://x
# eval in a comment
`
	got := analyze(t, "a.sh", src).Constructs
	want := []domain.Construct{
		{Kind: domain.ConstructDynamicCode, Line: 1, Detail: "eval"},
		{Kind: domain.ConstructDynamicCode, Line: 2, Detail: "eval"},
		{Kind: domain.ConstructShellCommand, Line: 4, Detail: "download piped into a shell"},
		{Kind: domain.ConstructShellCommand, Line: 5, Detail: "download piped into a shell"},
	}
	if !slices.Equal(got, want) {
		t.Fatalf("constructs = %+v\nwant         %+v", got, want)
	}
}

func TestTestFiles(t *testing.T) {
	for p, want := range map[string]bool{
		"scripts/tests/install_test.sh": true, "test/x.bats": true, "scripts/test_lib.sh": true, "scripts/install.sh": false,
	} {
		if got := analyze(t, p, "").Test; got != want {
			t.Errorf("%s: test = %v, want %v", p, got, want)
		}
	}
}
